-- HiveMind on PostgreSQL. GENERATED by deploy/postgres/make-schema.mjs from the SQLite database: edit that script, not this file.
-- 31 tables, 35 indexes. Safe to run more than once.

CREATE TABLE IF NOT EXISTS "articles" (
  "url" text PRIMARY KEY,
  "story_key" text NOT NULL,
  "title" text NOT NULL,
  "outlet" text NOT NULL,
  "publication" text NOT NULL,
  "published_at" bigint NOT NULL,
  "first_seen" bigint
);

CREATE TABLE IF NOT EXISTS "audits" (
  "key" text PRIMARY KEY,
  "verdict" text NOT NULL,
  "note" text,
  "reviewer" text,
  "reason" text,
  "at" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "auth_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ts" bigint NOT NULL,
  "event" text NOT NULL,
  "email" text,
  "ip" text,
  "detail" text
);

CREATE TABLE IF NOT EXISTS "authors" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "profile" text NOT NULL,
  "active" bigint NOT NULL DEFAULT 1,
  "created_at" bigint NOT NULL,
  "updated_at" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "briefs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "created_at" bigint NOT NULL,
  "company" text,
  "opp_key" text NOT NULL,
  "sector" text,
  "topic" text,
  "author_id" text,
  "brief" text NOT NULL,
  "model" text,
  "status" text NOT NULL DEFAULT 'pending',
  "note" text,
  "decided_at" bigint
);

CREATE TABLE IF NOT EXISTS "enrichments" (
  "key" text PRIMARY KEY,
  "wire" text,
  "content_type" text,
  "entities" text,
  "topics" text,
  "pathways" text,
  "source" text,
  "enriched_at" bigint NOT NULL,
  "sentiment" text,
  "stance" text,
  "sentiment_at" bigint
);

CREATE TABLE IF NOT EXISTS "entity_aliases" (
  "alias" text PRIMARY KEY,
  "canonical" text NOT NULL,
  "at" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "forecast_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "topic" text NOT NULL,
  "made_at" bigint NOT NULL,
  "target_at" bigint NOT NULL,
  "horizon" bigint NOT NULL,
  "predicted" double precision NOT NULL,
  "lo" double precision,
  "hi" double precision,
  "naive" double precision,
  "actual" double precision,
  "evaluated_at" bigint
);

CREATE TABLE IF NOT EXISTS "fulltext_tries" (
  "key" text PRIMARY KEY,
  "tries" bigint NOT NULL DEFAULT 0,
  "last_at" bigint NOT NULL,
  "result" text
);

CREATE TABLE IF NOT EXISTS "job_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" text NOT NULL,
  "trigger" text NOT NULL,
  "status" text NOT NULL,
  "started_at" bigint NOT NULL,
  "finished_at" bigint,
  "summary" text NOT NULL DEFAULT '',
  "stats" text NOT NULL DEFAULT '{}',
  "error" text
);

CREATE TABLE IF NOT EXISTS "journalists" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "publication" text,
  "beat" text,
  "designation" text,
  "city" text,
  "state" text,
  "country" text,
  "email" text,
  "phone" text,
  "linkedin" text,
  "twitter" text,
  "profile_url" text,
  "articles" text NOT NULL DEFAULT '[]',
  "synced_at" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "meta" (
  "k" text PRIMARY KEY,
  "v" text
);

CREATE TABLE IF NOT EXISTS "ocr_angle_matches" (
  "article_id" text NOT NULL,
  "opp_key" text NOT NULL,
  "company" text NOT NULL,
  "fit" double precision NOT NULL,
  "angle" text,
  "matched_at" bigint NOT NULL,
  PRIMARY KEY (article_id, opp_key)
);

CREATE TABLE IF NOT EXISTS "ocr_articles" (
  "id" text PRIMARY KEY,
  "source" text NOT NULL,
  "edition_date" text NOT NULL,
  "page" bigint,
  "headline" text NOT NULL,
  "body" text NOT NULL,
  "hash" text,
  "words" bigint NOT NULL DEFAULT 0,
  "candidate" bigint NOT NULL DEFAULT 0,
  "signals" text,
  "kind" text,
  "author" text,
  "why" text,
  "classified_at" bigint,
  "model" text,
  "fetched_at" bigint NOT NULL,
  "author_checked" bigint,
  "title" text,
  "title_source" text,
  "merged_into" text
);

CREATE TABLE IF NOT EXISTS "ocr_pages" (
  "key" text PRIMARY KEY,
  "at" bigint NOT NULL,
  "groups" bigint NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "reading_reviews" (
  "key" text NOT NULL,
  "model" text NOT NULL,
  "agrees" bigint NOT NULL,
  "note" text,
  "at" bigint NOT NULL,
  PRIMARY KEY (key, model)
);

CREATE TABLE IF NOT EXISTS "reading_versions" (
  "key" text NOT NULL,
  "at" bigint NOT NULL,
  "basis" text NOT NULL,
  "analysis" text NOT NULL,
  PRIMARY KEY (key, at)
);

CREATE TABLE IF NOT EXISTS "readings" (
  "key" text PRIMARY KEY,
  "basis" text NOT NULL,
  "analysis" text NOT NULL,
  "read_at" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "rec_outcomes" (
  "rec_id" bigint PRIMARY KEY,
  "evaluated_at" bigint NOT NULL,
  "hit" bigint NOT NULL,
  "peak_ratio" double precision,
  "peak_origins" bigint,
  "base_share" double precision,
  "peak_share" double precision
);

CREATE TABLE IF NOT EXISTS "recommendation_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ts" bigint NOT NULL,
  "as_of" bigint NOT NULL,
  "company" text NOT NULL,
  "opp_key" text NOT NULL,
  "sector" text,
  "label" text,
  "level" text,
  "score" double precision,
  "action" text,
  "stage" text,
  "kind" text,
  "components" text,
  "evidence" text,
  "reason" text,
  "voided" bigint NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "runs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "started_at" bigint NOT NULL,
  "updated_at" bigint NOT NULL,
  "finished_at" bigint,
  "model" text,
  "headlines" bigint,
  "publications" bigint,
  "per_publication" text,
  "total" bigint,
  "done" bigint NOT NULL DEFAULT 0,
  "target_date" text
);

CREATE TABLE IF NOT EXISTS "sessions" (
  "id_hash" text PRIMARY KEY,
  "user_id" text NOT NULL,
  "created_at" bigint NOT NULL,
  "last_seen" bigint NOT NULL,
  "expires_at" bigint NOT NULL,
  "ip" text,
  "ua" text
);

CREATE TABLE IF NOT EXISTS "signals" (
  "topic" text NOT NULL,
  "source" text NOT NULL,
  "t" bigint NOT NULL,
  "value" double precision NOT NULL,
  PRIMARY KEY (topic, source, t)
);

CREATE TABLE IF NOT EXISTS "stories" (
  "key" text PRIMARY KEY,
  "title" text NOT NULL,
  "url" text NOT NULL,
  "snippet" text NOT NULL DEFAULT '',
  "published_at" bigint NOT NULL,
  "day" text NOT NULL,
  "first_seen" bigint NOT NULL,
  "last_seen" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "story_dupes" (
  "key" text PRIMARY KEY,
  "canonical" text,
  "reason" text NOT NULL,
  "at" bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS "topic_checks" (
  "story_key" text NOT NULL,
  "topic_id" text NOT NULL,
  "fits" bigint NOT NULL,
  "why" text,
  "at" bigint NOT NULL,
  PRIMARY KEY (story_key, topic_id)
);

CREATE TABLE IF NOT EXISTS "topic_matches" (
  "company" text NOT NULL,
  "topic" text NOT NULL,
  "sector" text NOT NULL,
  "relevance" double precision NOT NULL,
  "channel" text,
  "front" text,
  "why" text,
  "angle" text,
  "judged_at" bigint NOT NULL,
  "story_count" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (company, topic, sector)
);

CREATE TABLE IF NOT EXISTS "topics" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "bracket" text,
  "aliases" text NOT NULL DEFAULT '[]',
  "count" bigint NOT NULL DEFAULT 0,
  "created_at" bigint NOT NULL,
  "merged_into" text,
  "merged_at" bigint
);

CREATE TABLE IF NOT EXISTS "usage_daily" (
  "day" text NOT NULL,
  "service" text NOT NULL,
  "calls" bigint NOT NULL DEFAULT 0,
  "errors" bigint NOT NULL DEFAULT 0,
  "tokens_in" bigint NOT NULL DEFAULT 0,
  "tokens_out" bigint NOT NULL DEFAULT 0,
  "cache_read" bigint NOT NULL DEFAULT 0,
  "batch_tokens" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (day, service)
);

CREATE TABLE IF NOT EXISTS "users" (
  "id" text PRIMARY KEY,
  "email" text NOT NULL UNIQUE,
  "name" text NOT NULL,
  "pw_hash" text NOT NULL,
  "role" text NOT NULL DEFAULT 'member',
  "status" text NOT NULL DEFAULT 'pending',
  "created_at" bigint NOT NULL,
  "last_login_at" bigint,
  "failed_count" bigint NOT NULL DEFAULT 0,
  "locked_until" bigint
);

CREATE TABLE IF NOT EXISTS "web_checks" (
  "topic" text NOT NULL,
  "source" text NOT NULL,
  "at" bigint NOT NULL,
  "data" text NOT NULL,
  PRIMARY KEY (topic, source, at)
);

